const crypto = require('crypto');
const secret = $env.ACTION_WEBHOOK_SECRET;
if (!secret) throw new Error('ACTION_WEBHOOK_SECRET is not configured');
const signature = $json.headers?.['x-autosfera-signature'] || '';
const raw = typeof $json.body === 'string' ? $json.body : JSON.stringify($json.body);
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
if (signature.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) throw new Error('Invalid Action Gateway signature');
const job = typeof $json.body === 'string' ? JSON.parse($json.body) : $json.body;
if (!['lead', 'test_drive', 'service'].includes(job.kind)) throw new Error('Unsupported action kind');
return [{json: job}];

const crypto = require('crypto');
const callback = {action_id: $json.action_id, dealer_id: $json.dealer_id, trace_id: $json.trace_id, status: 'completed', result: {provider: 'n8n-sandbox', external_id: $execution.id}};
const raw = JSON.stringify(callback);
const signature = crypto.createHmac('sha256', $env.ACTION_WEBHOOK_SECRET).update(raw).digest('hex');
return [{json: {raw, signature}}];
